import{_ as e,o as n,c as t,a2 as i}from"./chunks/framework.BLWd95NW.js";const k=JSON.parse('{"title":"Backend & Native Platform","description":"Peta integrasi API dan konfigurasi Android/iOS untuk project Flutter.","frontmatter":{"title":"Backend & Native Platform","description":"Peta integrasi API dan konfigurasi Android/iOS untuk project Flutter."},"headers":[],"relativePath":"guide/backend-native.md","filePath":"guide/backend-native.md","lastUpdated":1793502723000}'),s={name:"guide/backend-native.md"};function r(d,a,l,o,u,p){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="backend-native-platform" tabindex="-1">Backend &amp; Native Platform <a class="header-anchor" href="#backend-native-platform" aria-label="Permalink to &quot;Backend &amp; Native Platform&quot;">​</a></h1><p>Halaman ini menjadi peta saat aplikasi Flutter mulai berhubungan dengan server atau fitur perangkat. Kode UI dan state tetap tinggal di <code>lib/</code>; konfigurasi yang khusus Android/iOS ditempatkan di folder platform masing-masing.</p><h2 id="arsitektur-yang-dianjurkan" tabindex="-1">Arsitektur yang dianjurkan <a class="header-anchor" href="#arsitektur-yang-dianjurkan" aria-label="Permalink to &quot;Arsitektur yang dianjurkan&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Widget / View</span></span>
<span class="line"><span>    ↓ aksi pengguna</span></span>
<span class="line"><span>Controller / State (GetX atau state management lain)</span></span>
<span class="line"><span>    ↓ meminta data</span></span>
<span class="line"><span>Provider / Repository</span></span>
<span class="line"><span>    ↓ HTTP request</span></span>
<span class="line"><span>Backend / API</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><ul><li><code>models/</code> mengubah JSON API menjadi object Dart yang type-safe.</li><li><code>providers/</code> atau <code>services/</code> menyimpan base URL, request, dan parsing response.</li><li><code>controllers/</code> mengelola loading, error, dan state untuk UI.</li><li><code>views/</code> hanya menampilkan state; jangan simpan API key atau request rumit di widget.</li></ul><h2 id="audit-source-saat-ini" tabindex="-1">Audit source saat ini <a class="header-anchor" href="#audit-source-saat-ini" aria-label="Permalink to &quot;Audit source saat ini&quot;">​</a></h2><p>Materi yang telah terindeks memuat <strong>67 modul</strong>, <strong>391 source files</strong>, dan <strong>140 referensi package</strong>. Beginner Track mencakup Dart, Flutter, HTTP/API, dan GetX; Intermediate Track melanjutkan ke responsive layout dan animasi; Advanced Track membawa Firebase serta Supabase sampai auth, CRUD, storage, dan realtime data.</p><p>Snapshot lama belum menyimpan file platform Android/iOS sebagai source tab. Generator sekarang diperluas supaya saat dijalankan terhadap folder latihan asli, file konfigurasi native yang relevan ikut didokumentasikan—tanpa memasukkan output build.</p><h2 id="jalur-cloud-backend" tabindex="-1">Jalur cloud backend <a class="header-anchor" href="#jalur-cloud-backend" aria-label="Permalink to &quot;Jalur cloud backend&quot;">​</a></h2><p>Setelah menguasai HTTP dan state management, lanjutkan ke track cloud berikut:</p><ul><li><a href="/flutter-web-docs/guide/firebase-firestore-basics">Firebase &amp; Cloud Firestore</a> untuk inisialisasi Firebase dan membaca collection.</li><li><a href="/flutter-web-docs/guide/firebase-auth-crud">Firebase Auth &amp; Firestore CRUD</a> untuk session, verifikasi email, reset password, dan CRUD realtime.</li><li><a href="/flutter-web-docs/guide/supabase-auth-storage-crud">Supabase Auth, Storage &amp; CRUD</a> untuk autentikasi, Postgres realtime, RLS, upload gambar, dan Storage.</li></ul><h2 id="android-dan-ios" tabindex="-1">Android dan iOS <a class="header-anchor" href="#android-dan-ios" aria-label="Permalink to &quot;Android dan iOS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kebutuhan</th><th>Android</th><th>iOS</th></tr></thead><tbody><tr><td>Permission</td><td><code>android/app/src/main/AndroidManifest.xml</code></td><td><code>ios/Runner/Info.plist</code></td></tr><tr><td>Entry native</td><td><code>MainActivity.kt</code> atau <code>MainActivity.java</code></td><td><code>AppDelegate.swift</code></td></tr><tr><td>Dependency/build</td><td><code>build.gradle(.kts)</code>, <code>settings.gradle(.kts)</code></td><td><code>Podfile</code>, Xcode project</td></tr><tr><td>App icon/splash</td><td>resource <code>mipmap</code>/<code>drawable</code></td><td><code>Assets.xcassets</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Jangan taruh secret di aplikasi</p><p>API key yang benar-benar rahasia tidak aman bila diletakkan di Flutter karena binary aplikasi dapat diperiksa. Gunakan backend sebagai perantara untuk secret, validasi request, dan aturan bisnis sensitif. Untuk key publik/restricted, gunakan environment/build configuration dan batasi pemakaiannya di sisi provider.</p></div><h2 id="menghasilkan-ulang-source-docs" tabindex="-1">Menghasilkan ulang source docs <a class="header-anchor" href="#menghasilkan-ulang-source-docs" aria-label="Permalink to &quot;Menghasilkan ulang source docs&quot;">​</a></h2><p>Jika folder modul ada di luar repository dokumentasi ini, jalankan generator source terlebih dahulu, kemudian bangun VitePress:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> tools/generate_code_data.py</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> /path/ke/flutter_beginner_lesson</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> docs:build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Generator akan mengabaikan <code>build/</code>, <code>.dart_tool/</code>, dan dependency generated agar dokumentasi tetap fokus ke source yang perlu dipelajari.</p>`,18)])])}const m=e(s,[["render",r]]);export{k as __pageData,m as default};
